from collections import deque
class Solution:
    def countSpecialNodes(self, n, edges, x, y, z):
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v); adj[v].append(u)
        def bfs(s):
            d = [-1] * n; d[s] = 0; q = deque([s])
            while q:
                u = q.popleft()
                for w in adj[u]:
                    if d[w] < 0:
                        d[w] = d[u] + 1; q.append(w)
            return d
        dx, dy, dz = bfs(x), bfs(y), bfs(z)
        ans = 0
        for i in range(n):
            a, b, c = sorted((dx[i], dy[i], dz[i]))
            if a * a + b * b == c * c:
                ans += 1
        return ans

