class Solution {
public:
    int countSpecialNodes(int n, vector<vector<int>>& edges, int x, int y, int z) {
        vector<vector<int>> adj(n);
        for (auto& e : edges) { adj[e[0]].push_back(e[1]); adj[e[1]].push_back(e[0]); }
        auto bfs = [&](int s) {
            vector<int> d(n, -1); d[s] = 0; queue<int> q; q.push(s);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int w : adj[u]) if (d[w] < 0) { d[w] = d[u] + 1; q.push(w); }
            }
            return d;
        };
        auto dx = bfs(x), dy = bfs(y), dz = bfs(z);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            long a[3] = {dx[i], dy[i], dz[i]};
            sort(a, a + 3);
            if (a[0]*a[0] + a[1]*a[1] == a[2]*a[2]) ans++;
        }
        return ans;
    }
};

