class Solution {
    public int countSpecialNodes(int n, int[][] edges, int x, int y, int z) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        int[] dx = bfs(adj, n, x), dy = bfs(adj, n, y), dz = bfs(adj, n, z);
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int[] a = {dx[i], dy[i], dz[i]};
            Arrays.sort(a);
            if ((long)a[0]*a[0] + (long)a[1]*a[1] == (long)a[2]*a[2]) ans++;
        }
        return ans;
    }
    private int[] bfs(List<List<Integer>> adj, int n, int s) {
        int[] d = new int[n]; Arrays.fill(d, -1); d[s] = 0;
        Queue<Integer> q = new LinkedList<>(); q.add(s);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int w : adj.get(u)) if (d[w] < 0) { d[w] = d[u] + 1; q.add(w); }
        }
        return d;
    }
}

