var countSpecialNodes = function(n, edges, x, y, z) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    function bfs(s) {
        const d = new Array(n).fill(-1); d[s] = 0;
        const q = [s];
        for (let h = 0; h < q.length; h++) {
            const u = q[h];
            for (const w of adj[u]) if (d[w] < 0) { d[w] = d[u] + 1; q.push(w); }
        }
        return d;
    }
    const dx = bfs(x), dy = bfs(y), dz = bfs(z);
    let ans = 0;
    for (let i = 0; i < n; i++) {
        const a = [dx[i], dy[i], dz[i]].sort((p, q) => p - q);
        if (a[0]*a[0] + a[1]*a[1] === a[2]*a[2]) ans++;
    }
    return ans;
};
